import{_ as t,o as i,c as a,ap as e}from"./chunks/framework.BWFd5M2R.js";const g=JSON.parse('{"title":"DOCTYPE 的作用是什么？不声明会发生什么？","description":"","frontmatter":{"password":"f364e34a3743eacf1767066da4b2699469e2f9fab3b63fdd112c672a3805497e"},"headers":[],"relativePath":"HTML/DOCTYPE.md","filePath":"HTML/DOCTYPE.md","lastUpdated":1773652575000}'),l={name:"HTML/DOCTYPE.md"};function n(d,s,o,r,h,p){return i(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="doctype-的作用是什么-不声明会发生什么" tabindex="-1">DOCTYPE 的作用是什么？不声明会发生什么？ <a class="header-anchor" href="#doctype-的作用是什么-不声明会发生什么" aria-label="Permalink to “DOCTYPE 的作用是什么？不声明会发生什么？”">​</a></h1><p><code>&lt;!DOCTYPE html&gt;</code> 是一条<strong>文档类型声明</strong>，告诉浏览器用哪种规则来解析这个 HTML 文档。</p><h3 id="核心作用-触发标准模式-standards-mode" tabindex="-1">核心作用：触发标准模式（Standards Mode） <a class="header-anchor" href="#核心作用-触发标准模式-standards-mode" aria-label="Permalink to “核心作用：触发标准模式（Standards Mode）”">​</a></h3><p>浏览器有两种主要渲染模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>触发条件</th><th>行为</th></tr></thead><tbody><tr><td><strong>标准模式</strong></td><td>有正确的 DOCTYPE</td><td>按 W3C/WHATWG 规范渲染</td></tr><tr><td><strong>怪异模式</strong> (Quirks Mode)</td><td>缺少或错误的 DOCTYPE</td><td>模拟旧版 IE/Netscape 的 bug 行为</td></tr></tbody></table><h2 id="不声明-doctype-会发生什么" tabindex="-1">不声明 DOCTYPE 会发生什么？ <a class="header-anchor" href="#不声明-doctype-会发生什么" aria-label="Permalink to “不声明 DOCTYPE 会发生什么？”">​</a></h2><p>浏览器会进入<strong>怪异模式（Quirks Mode）</strong>，具体影响包括：</p><p><strong>盒模型不同</strong></p><ul><li>怪异模式下 <code>width</code> 包含 <code>padding</code> 和 <code>border</code>（类似 <code>box-sizing: border-box</code>），而标准模式下不包含</li></ul><p><strong>行内元素的垂直对齐</strong></p><ul><li>近似标准模式（Limited Quirks Mode）下，行高、对齐与标准模式不一致</li></ul><blockquote><p>注：图片底部「神秘空白」多由<strong>行内 + 基线对齐</strong>（<code>vertical-align</code> 默认）引起，<strong>标准模式里也很常见</strong>，不单独归因于「没写 DOCTYPE」。用 <code>display: block</code> 或调整 <code>vertical-align</code> 即可。</p></blockquote><p><strong>字体与行高计算差异</strong></p><ul><li>部分字体大小继承行为不一致</li></ul><p><strong><code>overflow</code> 处理不同</strong></p><ul><li>某些情况下父元素不会被子元素撑开</li></ul><p><strong><code>height: 100%</code> 行为异常</strong></p><ul><li>百分比高度的计算参考基准不同</li></ul><h2 id="现代写法" tabindex="-1">现代写法 <a class="header-anchor" href="#现代写法" aria-label="Permalink to “现代写法”">​</a></h2><p>HTML5 的 DOCTYPE 极简，不再需要引用 DTD：</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DOCTYPE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>历史上 HTML 4 的 DOCTYPE 很冗长，比如：</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DOCTYPE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HTML</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PUBLIC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-//W3C//DTD HTML 4.01 Transitional//EN&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;http://www.w3.org/TR/html4/loose.dtd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>现在一律用 <code>&lt;!DOCTYPE html&gt;</code> 即可，简洁且向前兼容。</p><h3 id="进阶-模式不止「怪异-标准」两种" tabindex="-1">进阶：模式不止「怪异 / 标准」两种 <a class="header-anchor" href="#进阶-模式不止「怪异-标准」两种" aria-label="Permalink to “进阶：模式不止「怪异 / 标准」两种”">​</a></h3><p>部分浏览器历史上还有 <strong>Limited Quirks Mode</strong>（近似标准、少量规则仍偏怪异）等中间状态；<strong>未写 DOCTYPE</strong> 或写法异常时，<strong>具体走哪种模式因浏览器与版本而异</strong>。工程上仍建议<strong>始终</strong>使用 <code>&lt;!DOCTYPE html&gt;</code>，不要依赖怪异模式下的布局「巧合」。 <strong>一句话总结</strong>：DOCTYPE 是浏览器的「模式开关」；没有合法 DOCTYPE 容易掉进怪异或近似怪异行为，跨浏览器表现更难预测。</p>`,26)])])}const c=t(l,[["render",n]]);export{g as __pageData,c as default};
